### anonymization.ts
type ReplacementPair = {
  original: string;
  placeholder: string;
};

/** Replaces literal PII values in JSON-compatible documents and restores them in outputs. */
export class PiiAnonymizationWrapper {
  #placeholderToOriginal = new Map<string, string>();
  #replacementPairs: readonly ReplacementPair[];

  constructor(piiValues: readonly string[]) {
    const originalToPlaceholder = new Map<string, string>();

    for (const value of piiValues) {
      if (value.length === 0) {
        throw new TypeError("PII values must not be empty.");
      }

      if (!originalToPlaceholder.has(value)) {
        const placeholder = `[PII_${String(originalToPlaceholder.size + 1).padStart(3, "0")}]`;
        originalToPlaceholder.set(value, placeholder);
        this.#placeholderToOriginal.set(placeholder, value);
      }
    }

    this.#replacementPairs = [...originalToPlaceholder.entries()]
      .map(([original, placeholder]) => ({ original, placeholder }))
      .sort((left, right) => right.original.length - left.original.length);
  }

  /** Returns a deep transformed copy with configured PII values replaced by placeholders. */
  sanitize<T>(document: T): T {
    return transformDocument(document, (value) => this.replaceOriginals(value));
  }

  /** Returns a deep transformed copy with known placeholders replaced by original PII values. */
  restore<T>(output: T): T {
    return transformDocument(output, (value) => this.restorePlaceholders(value));
  }

  /** Replaces configured original values in one string without interpreting them as regexes. */
  private replaceOriginals(value: string): string {
    return this.#replacementPairs.reduce(
      (current, pair) => replaceLiteral(current, pair.original, pair.placeholder),
      value,
    );
  }

  /** Restores only placeholders created by this wrapper instance. */
  private restorePlaceholders(value: string): string {
    return [...this.#placeholderToOriginal.entries()].reduce(
      (current, [placeholder, original]) => replaceLiteral(current, placeholder, original),
      value,
    );
  }
}

/** Recursively transforms string values while preserving JSON-compatible document structure. */
function transformDocument<T>(value: T, transformString: (value: string) => string): T {
  if (typeof value === "string") {
    return transformString(value) as T;
  }

  if (Array.isArray(value)) {
    return value.map((item) => transformDocument(item, transformString)) as T;
  }

  if (value !== null && typeof value === "object") {
    const transformed: Record<string, unknown> = {};
    for (const [key, child] of Object.entries(value)) {
      transformed[key] = transformDocument(child, transformString);
    }
    return transformed as T;
  }

  return value;
}

/** Replaces all literal occurrences of a value without regular-expression semantics. */
function replaceLiteral(value: string, search: string, replacement: string): string {
  return value.split(search).join(replacement);
}

### domain.ts
export type Money = {
  minorUnits: number;
  currency: string;
};

export type SourceRef = string;

export type NarrativeConsistencyOutcome = "CONSISTENT" | "CONTRADICTS";

export type NarrativeCheckInput = {
  claimNarrative: string;
  appraisalNarrative: string;
  sourceRefs: SourceRef[];
};

export type NarrativeCheckResponse = {
  outcome: NarrativeConsistencyOutcome;
};

export type NarrativeCheck = {
  response: NarrativeCheckResponse;
  sourceRefs: SourceRef[];
};

export interface NarrativeConsistencyChecker {
  check(input: NarrativeCheckInput): NarrativeCheck;
}

export type LineItem = {
  itemCode: string;
  description: string;
  quantity: number;
  total: Money;
  sourceRef: SourceRef;
};

export type Practice = {
  claimId: string;
  policyId: string;
  narrative: string;
  currency: string;
  sourceRef: SourceRef;
};

export type Appraisal = {
  appraisalId: string;
  claimId: string;
  narrative: string;
  lines: LineItem[];
  total: Money;
  sourceRef: SourceRef;
};

export type Invoice = {
  invoiceId: string;
  claimId: string;
  lines: LineItem[];
  total: Money;
  sourceRef: SourceRef;
};

export type PolicyConditions = {
  policyId: string;
  claimId: string;
  covered: boolean;
  limit: Money;
  deductible: Money;
  sourceRef: SourceRef;
};

export type W2Input = {
  practice: Practice;
  appraisal: Appraisal;
  invoice: Invoice;
  policy: PolicyConditions;
};

export type ProposedDecision = "LIQUIDATE" | "DO_NOT_LIQUIDATE";

export type Evidence = {
  code: string;
  message: string;
  sourceRefs: SourceRef[];
};

export type LineComparison = {
  itemCode: string;
  appraisalAmount: Money;
  invoiceAmount: Money;
  candidateAmount: Money;
  matches: boolean;
  evidence: Evidence;
};

export type DeterministicAnalysis = {
  claimId: string;
  proposedDecision: ProposedDecision;
  payableAmount: Money | null;
  amountStatus: "COMPUTED" | "ZERO" | "NOT_COMPUTABLE";
  requiresHumanReview: boolean;
  issues: Evidence[];
  narrativeCheck?: NarrativeCheck;
  lineComparisons: LineComparison[];
  ruleVersion: string;
};

export type Motivation = {
  index: number;
  seed: string;
  response: string;
  facts: MotivationFacts;
};

export type MotivationFacts = {
  claim: {
    claimId: string;
    narrative: string;
    sourceRef: SourceRef;
  };
  appraisal: {
    narrative: string;
    total: Money | null;
    sourceRef: SourceRef;
  };
  invoice: {
    total: Money | null;
    sourceRef: SourceRef;
  };
  policy: {
    covered: boolean | null;
    limit: Money | null;
    deductible: Money | null;
    sourceRef: SourceRef;
  };
  documents: {
    appraisalTotal: Money | null;
    invoiceTotal: Money | null;
    appraisalLines: Array<{ itemCode: string; amount: Money; sourceRef: SourceRef }>;
    invoiceLines: Array<{ itemCode: string; amount: Money; sourceRef: SourceRef }>;
  };
};

export type LiquidationProposal = DeterministicAnalysis & {
  motivation: Motivation;
};

### file-runner.ts
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import type {
  Appraisal,
  DeterministicAnalysis,
  Evidence,
  Invoice,
  LiquidationProposal,
  Money,
  NarrativeConsistencyOutcome,
  PolicyConditions,
  Practice,
  W2Input,
} from "./domain.ts";
import { analyzeLiquidation } from "./liquidation.ts";
import { composeMotivation } from "./motivation.ts";
import { createFixtureNarrativeConsistencyChecker } from "./narrative-consistency.ts";

const SYNTHETIC_AUTH_TOKEN = "synthetic-valid-token";

const SOURCE_FILES = {
  practice: "gestionale-sinistri-practice-clm-001.json",
  appraisal: "servizio-periti-appraisal-app-001.json",
  invoice: "archivio-documentale-invoice-inv-001.json",
  policy: "sistema-polizze-policy-pol-001.json",
} as const;

const EXPECTED_SOURCE_SYSTEMS = {
  practice: "Gestionale Sinistri",
  appraisal: "Servizio Periti",
  invoice: "Archivio documentale",
  policy: "Sistema Polizze",
} as const;

export type MockFault =
  | "AUTHENTICATION_FAILURE"
  | "MISSING_APPRAISAL"
  | "INVALID_INVOICE";

export type W2MockRunOptions = {
  authToken?: string;
  fault?: MockFault;
  seed?: string;
};

export type W2RunErrorCode =
  | "AUTHENTICATION_FAILED"
  | "MISSING_SOURCE_FILE"
  | "INVALID_SOURCE_FILE"
  | "UNEXPECTED_RUNNER_ERROR";

export type W2RunStage = "AUTHENTICATION" | "INGESTION" | "RUNNER";

export type W2RunError = {
  code: W2RunErrorCode;
  message: string;
  retryable: boolean;
  stage: W2RunStage;
};

export type W3Referral = {
  code: "INVOICE_ABOVE_APPRAISAL_THRESHOLD" | "UNESTIMATED_INVOICE";
  message: string;
  thresholdPercent: number;
  variancePercent: number | null;
  appraisalAmount: Money;
  invoiceAmount: Money;
  sourceRefs: string[];
};

export type W2Routing = {
  next: "W2" | "W3" | "HUMAN_REVIEW";
  referral: W3Referral | null;
};

export type W2SourceRefs = {
  practice: string;
  appraisal: string;
  invoice: string;
  policy: string;
};

export type W2ExecutionResult =
  | {
      status: "COMPLETED";
      sources: W2SourceRefs;
      routing: W2Routing;
      proposal: LiquidationProposal;
    }
  | {
      status: "FAILED";
      error: W2RunError;
    };

type ExternalRecord<T> = {
  sourceSystem: string;
  sourceRef: string;
  record: T;
};

type ExternalPractice = Practice & {
  narrativeCheckFixture: NarrativeConsistencyOutcome;
};

type LoadedMockBundle = {
  practice: ExternalRecord<ExternalPractice>;
  appraisal: ExternalRecord<Appraisal>;
  invoice: ExternalRecord<Invoice>;
  policy: ExternalRecord<PolicyConditions>;
};

const W3_THRESHOLD_PERCENT = 30;

/** Represents a controlled failure at the synthetic integration boundary. */
class MockIntegrationError extends Error {
  public readonly code: W2RunErrorCode;
  public readonly retryable: boolean;
  public readonly stage: W2RunStage;

  constructor(
    code: W2RunErrorCode,
    message: string,
    retryable: boolean,
    stage: W2RunStage,
  ) {
    super(message);
    this.code = code;
    this.retryable = retryable;
    this.stage = stage;
  }
}

/** Simulates a shared credential check before reading any external-system mock. */
function authenticateMockSystems(token: string, fault?: MockFault): void {
  if (fault === "AUTHENTICATION_FAILURE" || token !== SYNTHETIC_AUTH_TOKEN) {
    throw new MockIntegrationError(
      "AUTHENTICATION_FAILED",
      "Synthetic external-system authentication failed.",
      false,
      "AUTHENTICATION",
    );
  }
}

/** Reads one external-system envelope and validates its source contract. */
function readExternalRecord<T>(
  directory: string,
  entity: keyof typeof SOURCE_FILES,
): ExternalRecord<T> {
  const fileName = SOURCE_FILES[entity];
  const filePath = join(directory, fileName);
  let raw: string;

  try {
    raw = readFileSync(filePath, "utf8");
  } catch {
    throw new MockIntegrationError(
      "MISSING_SOURCE_FILE",
      `Required mock source file is unavailable: ${fileName}.`,
      false,
      "INGESTION",
    );
  }

  let parsed: Partial<ExternalRecord<T>>;
  try {
    parsed = JSON.parse(raw) as Partial<ExternalRecord<T>>;
  } catch {
    throw new MockIntegrationError(
      "INVALID_SOURCE_FILE",
      `Invalid JSON in mock source file: ${fileName}.`,
      false,
      "INGESTION",
    );
  }

  if (
    parsed.sourceSystem !== EXPECTED_SOURCE_SYSTEMS[entity] ||
    !parsed.sourceRef ||
    !parsed.record
  ) {
    throw new MockIntegrationError(
      "INVALID_SOURCE_FILE",
      `Invalid mock source envelope: ${fileName}.`,
      false,
      "INGESTION",
    );
  }

  return parsed as ExternalRecord<T>;
}

/** Loads all four normalized external-system mocks after authentication succeeds. */
function loadMockBundle(directory: string, fault?: MockFault): LoadedMockBundle {
  if (fault === "MISSING_APPRAISAL") {
    throw new MockIntegrationError(
      "MISSING_SOURCE_FILE",
      `Required mock source file is unavailable: ${SOURCE_FILES.appraisal}.`,
      false,
      "INGESTION",
    );
  }

  const bundle = {
    practice: readExternalRecord<ExternalPractice>(directory, "practice"),
    appraisal: readExternalRecord<Appraisal>(directory, "appraisal"),
    invoice: readExternalRecord<Invoice>(directory, "invoice"),
    policy: readExternalRecord<PolicyConditions>(directory, "policy"),
  } satisfies LoadedMockBundle;

  if (!bundle.practice.record.narrativeCheckFixture) {
    throw new MockIntegrationError(
      "INVALID_SOURCE_FILE",
      `Practice mock does not declare narrativeCheckFixture: ${SOURCE_FILES.practice}.`,
      false,
      "INGESTION",
    );
  }

  if (fault === "INVALID_INVOICE") {
    bundle.invoice = {
      ...bundle.invoice,
      record: {
        ...bundle.invoice.record,
        claimId: `${bundle.invoice.record.claimId}-FAULT`,
      },
    };
  }

  return bundle;
}

/** Adapts source records to the normalized aggregate consumed by the W2 core. */
function adaptMockBundle(bundle: LoadedMockBundle): W2Input {
  return {
    practice: bundle.practice.record,
    appraisal: bundle.appraisal.record,
    invoice: bundle.invoice.record,
    policy: bundle.policy.record,
  };
}

/** Extracts source references retained in the completed test outcome. */
function extractSourceRefs(bundle: LoadedMockBundle): W2SourceRefs {
  return {
    practice: bundle.practice.sourceRef,
    appraisal: bundle.appraisal.sourceRef,
    invoice: bundle.invoice.sourceRef,
    policy: bundle.policy.sourceRef,
  };
}

/** Builds a W3 referral when invoice cost exceeds the synthetic appraisal threshold. */
function detectW3Referral(
  bundle: LoadedMockBundle,
  analysis: DeterministicAnalysis,
): W3Referral | null {
  if (
    analysis.amountStatus === "NOT_COMPUTABLE" ||
    analysis.narrativeCheck?.response.outcome !== "CONSISTENT"
  ) {
    return null;
  }

  const appraisalAmount = bundle.appraisal.record.total;
  const invoiceAmount = bundle.invoice.record.total;
  if (
    appraisalAmount.currency !== invoiceAmount.currency ||
    invoiceAmount.minorUnits <= appraisalAmount.minorUnits
  ) {
    return null;
  }

  if (appraisalAmount.minorUnits === 0) {
    return {
      code: "UNESTIMATED_INVOICE",
      message: "Invoice contains a positive amount without an appraisal baseline.",
      thresholdPercent: W3_THRESHOLD_PERCENT,
      variancePercent: null,
      appraisalAmount,
      invoiceAmount,
      sourceRefs: [bundle.appraisal.sourceRef, bundle.invoice.sourceRef],
    };
  }

  const variancePercent = Number(
    (((invoiceAmount.minorUnits - appraisalAmount.minorUnits) / appraisalAmount.minorUnits) * 100).toFixed(2),
  );
  if (variancePercent <= W3_THRESHOLD_PERCENT) {
    return null;
  }

  return {
    code: "INVOICE_ABOVE_APPRAISAL_THRESHOLD",
    message: "Invoice exceeds appraisal by more than the synthetic W3 threshold.",
    thresholdPercent: W3_THRESHOLD_PERCENT,
    variancePercent,
    appraisalAmount,
    invoiceAmount,
    sourceRefs: [bundle.appraisal.sourceRef, bundle.invoice.sourceRef],
  };
}

/** Blocks liquidation while preserving the deterministic candidate amount and W3 evidence. */
function applyW3Referral(
  analysis: DeterministicAnalysis,
  referral: W3Referral,
): DeterministicAnalysis {
  const referralEvidence: Evidence = {
    code: "W3_REFERRAL",
    message: referral.message,
    sourceRefs: referral.sourceRefs,
  };
  return {
    ...analysis,
    proposedDecision: "DO_NOT_LIQUIDATE",
    requiresHumanReview: true,
    issues: [...analysis.issues, referralEvidence],
  };
}

/** Selects the next local test-run destination from referral and human-review state. */
function buildRouting(
  analysis: DeterministicAnalysis,
  referral: W3Referral | null,
): W2Routing {
  return {
    next: referral ? "W3" : analysis.requiresHumanReview ? "HUMAN_REVIEW" : "W2",
    referral,
  };
}

/** Persists a complete wrapper outcome, including controlled failures. */
function persistOutcome(outputPath: string, result: W2ExecutionResult): void {
  mkdirSync(dirname(outputPath), { recursive: true });
  writeFileSync(outputPath, `${JSON.stringify(result, null, 2)}\n`, "utf8");
}

/** Reads external mocks, simulates auth, executes W2, and persists a test outcome. */
export function runW2MockBundle(
  directory: string,
  outputPath: string,
  options: W2MockRunOptions = {},
): W2ExecutionResult {
  try {
    authenticateMockSystems(options.authToken ?? SYNTHETIC_AUTH_TOKEN, options.fault);
    const bundle = loadMockBundle(directory, options.fault);
    const input = adaptMockBundle(bundle);
    const checker = createFixtureNarrativeConsistencyChecker(bundle.practice.record.narrativeCheckFixture);
    const initialAnalysis = analyzeLiquidation(input, checker);
    const referral = detectW3Referral(bundle, initialAnalysis);
    const analysis = referral ? applyW3Referral(initialAnalysis, referral) : initialAnalysis;
    const proposal: LiquidationProposal = {
      ...analysis,
      motivation: composeMotivation(
        input,
        analysis,
        options.seed ?? bundle.practice.record.claimId,
      ),
    };
    const result: W2ExecutionResult = {
      status: "COMPLETED",
      sources: extractSourceRefs(bundle),
      routing: buildRouting(analysis, referral),
      proposal,
    };
    persistOutcome(outputPath, result);
    return result;
  } catch (error) {
    const runError = error instanceof MockIntegrationError
      ? {
          code: error.code,
          message: error.message,
          retryable: error.retryable,
          stage: error.stage,
        }
      : {
          code: "UNEXPECTED_RUNNER_ERROR" as const,
          message: "Unexpected synthetic runner failure.",
          retryable: false,
          stage: "RUNNER" as const,
        };
    const result: W2ExecutionResult = { status: "FAILED", error: runError };
    persistOutcome(outputPath, result);
    return result;
  }
}

