    authToken: "invalid-synthetic-token",
  });

  assert.equal(result.status, "FAILED");
  assert.deepEqual(result.error, {
    code: "AUTHENTICATION_FAILED",
    message: "Synthetic external-system authentication failed.",
    retryable: false,
