 68:   sourceRefs: string[];
 69: };
 70: 
 71: export type W2Routing = {
 72:   next: "W2" | "W3" | "HUMAN_REVIEW";
 73:   referral: W3Referral | null;
 74: };
 75: 
 76: export type W2SourceRefs = {
 77:   practice: string;
 78:   appraisal: string;
 79:   invoice: string;
 80:   policy: string;
 81: };
 82: 
 83: export type W2ExecutionResult =
 84:   | {
 85:       status: "COMPLETED";
 86:       sources: W2SourceRefs;
 87:       routing: W2Routing;
 88:       proposal: LiquidationProposal;
 89:     }
 90:   | {
 91:       status: "FAILED";
 92:       error: W2RunError;
 93:     };
