 95: type ExternalRecord<T> = {
 96:   sourceSystem: string;
 97:   sourceRef: string;
 98:   record: T;
 99: };
100: 
101: type ExternalPractice = Practice & {
102:   narrativeCheckFixture: NarrativeConsistencyOutcome;
103: };
104: 
105: type LoadedMockBundle = {
106:   practice: ExternalRecord<ExternalPractice>;
107:   appraisal: ExternalRecord<Appraisal>;
108:   invoice: ExternalRecord<Invoice>;
109:   policy: ExternalRecord<PolicyConditions>;
110: };
111: 
112: const W3_THRESHOLD_PERCENT = 30;
113: 
114: /** Represents a controlled failure at the synthetic integration boundary. */
115: class MockIntegrationError extends Error {
116:   public readonly code: W2RunErrorCode;
117:   public readonly retryable: boolean;
118:   public readonly stage: W2RunStage;
119: 
120:   constructor(
121:     code: W2RunErrorCode,
122:     message: string,
123:     retryable: boolean,
124:     stage: W2RunStage,
125:   ) {
126:     super(message);
127:     this.code = code;
128:     this.retryable = retryable;
129:     this.stage = stage;
130:   }
131: }
132: 
133: /** Simulates a shared credential check before reading any external-system mock. */
134: function authenticateMockSystems(token: string, fault?: MockFault): void {
135:   if (fault === "AUTHENTICATION_FAILURE" || token !== SYNTHETIC_AUTH_TOKEN) {
136:     throw new MockIntegrationError(
137:       "AUTHENTICATION_FAILED",
138:       "Synthetic external-system authentication failed.",
139:       false,
140:       "AUTHENTICATION",
141:     );
142:   }
143: }
144: 
145: /** Reads one external-system envelope and validates its source contract. */
146: function readExternalRecord<T>(
147:   directory: string,
148:   entity: keyof typeof SOURCE_FILES,
149: ): ExternalRecord<T> {
150:   const fileName = SOURCE_FILES[entity];
151:   const filePath = join(directory, fileName);
152:   let raw: string;
153: 
154:   try {
155:     raw = readFileSync(filePath, "utf8");
156:   } catch {
157:     throw new MockIntegrationError(
158:       "MISSING_SOURCE_FILE",
159:       `Required mock source file is unavailable: ${fileName}.`,
160:       false,
161:       "INGESTION",
162:     );
163:   }
164: 
165:   let parsed: Partial<ExternalRecord<T>>;
166:   try {
167:     parsed = JSON.parse(raw) as Partial<ExternalRecord<T>>;
168:   } catch {
169:     throw new MockIntegrationError(
170:       "INVALID_SOURCE_FILE",
171:       `Invalid JSON in mock source file: ${fileName}.`,
172:       false,
173:       "INGESTION",
174:     );
175:   }
176: 
177:   if (
178:     parsed.sourceSystem !== EXPECTED_SOURCE_SYSTEMS[entity] ||
179:     !parsed.sourceRef ||
180:     !parsed.record
181:   ) {
182:     throw new MockIntegrationError(
183:       "INVALID_SOURCE_FILE",
184:       `Invalid mock source envelope: ${fileName}.`,
185:       false,
186:       "INGESTION",
187:     );
188:   }
189: 
190:   return parsed as ExternalRecord<T>;
191: }
192: 
193: /** Loads all four normalized external-system mocks after authentication succeeds. */
194: function loadMockBundle(directory: string, fault?: MockFault): LoadedMockBundle {
195:   if (fault === "MISSING_APPRAISAL") {
196:     throw new MockIntegrationError(
197:       "MISSING_SOURCE_FILE",
198:       `Required mock source file is unavailable: ${SOURCE_FILES.appraisal}.`,
199:       false,
200:       "INGESTION",
201:     );
202:   }
203: 
204:   const bundle = {
205:     practice: readExternalRecord<ExternalPractice>(directory, "practice"),
206:     appraisal: readExternalRecord<Appraisal>(directory, "appraisal"),
207:     invoice: readExternalRecord<Invoice>(directory, "invoice"),
208:     policy: readExternalRecord<PolicyConditions>(directory, "policy"),
209:   } satisfies LoadedMockBundle;
