211:   if (!bundle.practice.record.narrativeCheckFixture) {
212:     throw new MockIntegrationError(
213:       "INVALID_SOURCE_FILE",
214:       `Practice mock does not declare narrativeCheckFixture: ${SOURCE_FILES.practice}.`,
215:       false,
216:       "INGESTION",
217:     );
218:   }
