220:   if (fault === "INVALID_INVOICE") {
221:     bundle.invoice = {
222:       ...bundle.invoice,
223:       record: {
224:         ...bundle.invoice.record,
225:         claimId: `${bundle.invoice.record.claimId}-FAULT`,
226:       },
227:     };
228:   }
229: 
230:   return bundle;
231: }
