233: /** Adapts source records to the normalized aggregate consumed by the W2 core. */
234: function adaptMockBundle(bundle: LoadedMockBundle): W2Input {
235:   return {
236:     practice: bundle.practice.record,
237:     appraisal: bundle.appraisal.record,
238:     invoice: bundle.invoice.record,
239:     policy: bundle.policy.record,
240:   };
241: }
242: 
243: /** Extracts source references retained in the completed test outcome. */
244: function extractSourceRefs(bundle: LoadedMockBundle): W2SourceRefs {
245:   return {
246:     practice: bundle.practice.sourceRef,
247:     appraisal: bundle.appraisal.sourceRef,
248:     invoice: bundle.invoice.sourceRef,
249:     policy: bundle.policy.sourceRef,
250:   };
251: }
252: 
253: /** Builds a W3 referral when invoice cost exceeds the synthetic appraisal threshold. */
254: function detectW3Referral(
255:   bundle: LoadedMockBundle,
256:   analysis: DeterministicAnalysis,
257: ): W3Referral | null {
258:   if (
259:     analysis.amountStatus === "NOT_COMPUTABLE" ||
260:     analysis.narrativeCheck?.response.outcome !== "CONSISTENT"
261:   ) {
262:     return null;
263:   }
264: 
265:   const appraisalAmount = bundle.appraisal.record.total;
266:   const invoiceAmount = bundle.invoice.record.total;
267:   if (
268:     appraisalAmount.currency !== invoiceAmount.currency ||
269:     invoiceAmount.minorUnits <= appraisalAmount.minorUnits
270:   ) {
271:     return null;
272:   }
273: 
274:   if (appraisalAmount.minorUnits === 0) {
275:     return {
276:       code: "UNESTIMATED_INVOICE",
277:       message: "Invoice contains a positive amount without an appraisal baseline.",
278:       thresholdPercent: W3_THRESHOLD_PERCENT,
279:       variancePercent: null,
280:       appraisalAmount,
281:       invoiceAmount,
282:       sourceRefs: [bundle.appraisal.sourceRef, bundle.invoice.sourceRef],
283:     };
284:   }
285: 
286:   const variancePercent = Number(
287:     (((invoiceAmount.minorUnits - appraisalAmount.minorUnits) / appraisalAmount.minorUnits) * 100).toFixed(2),
288:   );
289:   if (variancePercent <= W3_THRESHOLD_PERCENT) {
290:     return null;
291:   }
292: 
293:   return {
294:     code: "INVOICE_ABOVE_APPRAISAL_THRESHOLD",
295:     message: "Invoice exceeds appraisal by more than the synthetic W3 threshold.",
296:     thresholdPercent: W3_THRESHOLD_PERCENT,
297:     variancePercent,
298:     appraisalAmount,
299:     invoiceAmount,
300:     sourceRefs: [bundle.appraisal.sourceRef, bundle.invoice.sourceRef],
301:   };
302: }
303: 
304: /** Blocks liquidation while preserving the deterministic candidate amount and W3 evidence. */
305: function applyW3Referral(
306:   analysis: DeterministicAnalysis,
307:   referral: W3Referral,
308: ): DeterministicAnalysis {
309:   const referralEvidence: Evidence = {
310:     code: "W3_REFERRAL",
311:     message: referral.message,
312:     sourceRefs: referral.sourceRefs,
313:   };
314:   return {
315:     ...analysis,
316:     proposedDecision: "DO_NOT_LIQUIDATE",
317:     requiresHumanReview: true,
318:     issues: [...analysis.issues, referralEvidence],
319:   };
320: }
321: 
322: /** Selects the next local test-run destination from referral and human-review state. */
323: function buildRouting(
324:   analysis: DeterministicAnalysis,
325:   referral: W3Referral | null,
326: ): W2Routing {
327:   return {
328:     next: referral ? "W3" : analysis.requiresHumanReview ? "HUMAN_REVIEW" : "W2",
329:     referral,
330:   };
331: }
332: 
333: /** Persists a complete wrapper outcome, including controlled failures. */
334: function persistOutcome(outputPath: string, result: W2ExecutionResult): void {
335:   mkdirSync(dirname(outputPath), { recursive: true });
336:   writeFileSync(outputPath, `${JSON.stringify(result, null, 2)}\n`, "utf8");
337: }
338: 
339: /** Reads external mocks, simulates auth, executes W2, and persists a test outcome. */
340: export function runW2MockBundle(
341:   directory: string,
342:   outputPath: string,
343:   options: W2MockRunOptions = {},
344: ): W2ExecutionResult {
345:   try {
346:     authenticateMockSystems(options.authToken ?? SYNTHETIC_AUTH_TOKEN, options.fault);
347:     const bundle = loadMockBundle(directory, options.fault);
348:     const input = adaptMockBundle(bundle);
349:     const checker = createFixtureNarrativeConsistencyChecker(bundle.practice.record.narrativeCheckFixture);
350:     const initialAnalysis = analyzeLiquidation(input, checker);
351:     const referral = detectW3Referral(bundle, initialAnalysis);
352:     const analysis = referral ? applyW3Referral(initialAnalysis, referral) : initialAnalysis;
353:     const proposal: LiquidationProposal = {
354:       ...analysis,
355:       motivation: composeMotivation(
356:         input,
357:         analysis,
358:         options.seed ?? bundle.practice.record.claimId,
359:       ),
360:     };

